def generate_parenthesis(n):
    def is_valid(s):
        balance = 0
        for c in s:
            balance += 1 if c == '(' else -1
            if balance < 0:
                return False
        return balance == 0

    result = []

    def generate_all(current):
        if len(current) == 2 * n:
            if is_valid(current):
                result.append(current)
            return
        generate_all(current + "(")
        generate_all(current + ")")

    generate_all("")
    return result


