#include <bits/stdc++.h>
using namespace std;

bool isValid(const string& s) {
    int balance = 0;
    for (char c : s) {
        balance += c == '(' ? 1 : -1;
        if (balance < 0) return false;
    }
    return balance == 0;
}

vector<string> result;

void generateAll(string& current, int n) {
    if ((int)current.size() == 2 * n) {
        if (isValid(current)) result.push_back(current);
        return;
    }
    current.push_back('(');
    generateAll(current, n);
    current.pop_back();

    current.push_back(')');
    generateAll(current, n);
    current.pop_back();
}

vector<string> generateParenthesis(int n) {
    result.clear();
    string current;
    generateAll(current, n);
    return result;
}

int main() {
    for (auto& s : generateParenthesis(3)) cout << s << " ";
    cout << endl;
    for (auto& s : generateParenthesis(1)) cout << s << " ";
    cout << endl;
    return 0;
}

